UPDATE "City" SET "published" = 1 WHERE "slug" IN ('hartford', 'durham');
UPDATE "City" SET "intro" = 'Hartford''s listings center on River Bend Bookshop in West Hartford, which hosts American Mah Jongg 101 beginner and 102 intermediate courses taught by Linda Houde, plus a regular open studio night. Its event pages ask players to bring a current National Mah Jongg League card. If you are new, take the 101 course first and then join open studio. Check the bookshop''s events page for the next course dates.' WHERE "slug" = 'hartford';
UPDATE "City" SET "intro" = 'Durham has two regular options. DSSOLVR, a taproom, hosts monthly beginner lessons and guided play on the second Thursday, and a free open play for experienced players on the fourth Thursday. North Regional Library runs a Learn to Play Mahjong session on Wednesday afternoons that welcomes beginners and covers American Mahjong. If you are new, start with the library session or the taproom beginner night. Check each calendar for current dates.' WHERE "slug" = 'durham';
